import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.BGlkWkwp.js";const b=JSON.parse('{"title":"Toolbar","description":"","frontmatter":{},"headers":[],"relativePath":"components/toolbar.md","filePath":"components/toolbar.md"}'),i={name:"components/toolbar.md"};function r(n,t,l,h,s,c){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="toolbar" tabindex="-1">Toolbar <a class="header-anchor" href="#toolbar" aria-label="Permalink to &quot;Toolbar&quot;">​</a></h1><p>Toolbar is the head of a container: a title and its actions on one line.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it as the head of a <a href="./panel">Panel</a>, a modal or a sheet. It always holds at least one action; a title alone is a heading, not a toolbar. Use <code>rule</code> when the content below does not start with a line of its own, <code>tail</code> when the last action is an icon button, and <code>two</code> for a title with a second line. Without <code>title</code>, the children are free, such as <a href="./tabs">Tabs</a>, which take the toolbar&#39;s height and meet its line.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td></td><td>The title, h2 on one line</td></tr><tr><td><code>titleId</code></td><td></td><td>The id of the title, for <code>aria-labelledby</code></td></tr><tr><td><code>rule</code></td><td><code>false</code></td><td>A line along the bottom</td></tr><tr><td><code>tail</code></td><td><code>false</code></td><td>The last action is an icon button</td></tr><tr><td><code>two</code></td><td><code>false</code></td><td>A title with a second line: the height grows</td></tr><tr><td><code>start</code></td><td></td><td>Before the title, such as back or close (a snippet)</td></tr><tr><td><code>end</code></td><td></td><td>The actions at the right end (a snippet)</td></tr><tr><td><code>children</code></td><td></td><td>Free content after the title</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The height is fixed: a small button with pad-md above and below (<code>--kata-height-toolbar</code>), with pad-md at the sides, and the controls inside are small buttons. The title is h2, trimmed to its ink, on one line with an ellipsis; nothing inside wraps. The actions sit at the right end, icon buttons side by side. With <code>tail</code> the padding on the right is pad-sm, so the icon&#39;s strokes line up with the content below. With <code>two</code> it is a container with padding: the height follows the content, with pad-md above and below, and the items side by side are all at its edges, so the first line of the title and the last line under it are trimmed there and their ink is pad-md from the edge. A control without a line or a surface inside reaches into that padding. It keeps its height in a vertical flex.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/toolbar/" title="Toolbar" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/toolbar/" target="_blank" rel="noopener">Toolbar</a></figcaption></figure>',10)])])}const m=e(i,[["render",r]]);export{b as __pageData,m as default};
